package model;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="bis_pre_inspections",uniqueConstraints=@UniqueConstraint(columnNames="operation_id"))
public class BisPreInspection { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="operation_id",nullable=false) private Long operationId; private String companyName; private String contactNumber; private String location; private String indianStandard; @Column(name="procedure_code") private String procedure; private LocalDate targetDate; private LocalDate finalDate; private Long assignedEngineerId; public Long getOperationId(){return operationId;} public void setOperationId(Long v){operationId=v;} public void setCompanyName(String v){companyName=v;} public void setContactNumber(String v){contactNumber=v;} public void setLocation(String v){location=v;} public void setIndianStandard(String v){indianStandard=v;} public void setProcedure(String v){procedure=v;} public void setTargetDate(LocalDate v){targetDate=v;} public void setFinalDate(LocalDate v){finalDate=v;} public void setAssignedEngineerId(Long v){assignedEngineerId=v;} }
